using UnityEngine;
namespace MotionStudio {public class NativePost:MonoBehaviour {public float bloom=.07f,exposure=1;public Color tint=Color.white;Material material;void Awake(){material=new Material(Resources.Load<Shader>("NativePost"));}void OnRenderImage(RenderTexture source,RenderTexture destination){var a=RenderTexture.GetTemporary(Mathf.Max(1,source.width/4),Mathf.Max(1,source.height/4),0,RenderTextureFormat.ARGBHalf);var b=RenderTexture.GetTemporary(a.width,a.height,0,RenderTextureFormat.ARGBHalf);material.SetFloat("_Mode",0);Graphics.Blit(source,a,material);material.SetFloat("_Mode",1);material.SetVector("_Direction",Vector2.right);Graphics.Blit(a,b,material);material.SetVector("_Direction",Vector2.up);Graphics.Blit(b,a,material);material.SetFloat("_Mode",2);material.SetTexture("_Glow",a);material.SetFloat("_Bloom",bloom);material.SetFloat("_Exposure",exposure);material.SetVector("_Tint",new Vector4(tint.r,tint.g,tint.b,1));bool was=GL.sRGBWrite;GL.sRGBWrite=QualitySettings.activeColorSpace==ColorSpace.Linear&&(destination==null||destination.sRGB);Graphics.Blit(source,destination,material);GL.sRGBWrite=was;RenderTexture.ReleaseTemporary(a);RenderTexture.ReleaseTemporary(b);}void OnDestroy(){if(material)Destroy(material);}}}
